using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BoostEffect", menuName = "Data/Battle/Effects/Boost Effect")]
public class BoostEffect : Effect
{
	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		if (amount >= EffectsValues.INFINITY)
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("BoostInf_D");
		}
		return base.GetEffectDescription(amount);
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitsDiceActivation>().Boosted(boost: true);
		if (effectAmount >= EffectsValues.INFINITY)
		{
			return effectAmount;
		}
		return effectAmount - 1;
	}
}
